import{_ as t,o as e,c as p,a5 as l}from"./chunks/framework.BPFk9-tb.js";const b=JSON.parse('{"title":"写作课作业-073","description":"","frontmatter":{"date":"2020-10-02T23:00:25","title":"写作课作业-073","categories":["写作","作业","微信互联网平民创业"],"tags":["写作","作业","微信互联网平民创业"]},"headers":[],"relativePath":"posts/homework/073.md","filePath":"posts/homework/073.md"}'),c={name:"posts/homework/073.md"};function a(s,o,r,u,_,i){return e(),p("div",null,[...o[0]||(o[0]=[l("<blockquote><p>9.30写作作业：《微信互联网平民创业》之《5.为什么要格外重视视频号？》</p></blockquote><blockquote><p>在能力具备的情况下，错过机会就是极为可惜的事儿了，是吧?更何况，经过一小段时 间的学习与思考，你的认知，以及你的商业能力都有了很大的提升，所以，若是进步过 后的你竟然还是错过了机会，那么，肯定更为可惜......</p></blockquote><blockquote><p>微信视频号在 2020 年上半年开始内测的时候，很多所谓的「业内人士」所谓的「专家」都不看好。</p><p>越是微博大号、越是抖音快手大号，越是不重视微信视频号......</p></blockquote><p>既得利益者，不希望看到改变，如果改变回</p><blockquote><p>微信肯定是所有提供短视频服务的平台之中「唯一绝对不缺用户的」</p></blockquote><blockquote><p>微信有另外一个「杀手锏」，或者也可以称为是 「护城河」的东⻄:微信支付。除了微信之外，你再也找不到任何一个其他应用可以做 到全方位的全覆盖了:</p><ul><li>用户全覆盖</li><li>社交全覆盖</li><li>内容品类全覆盖</li><li>交易环节全覆盖</li></ul></blockquote><blockquote><p>这很可能是未来五到十年里所能遇到的最后一次互联网流量瓜分机会**......**</p><p>仔细琢磨这句话罢 —— 用越⻓的时间琢磨越好，越使劲越好。因为，未来的 6~18 个 月，不管你自己有没有发生变化，你必然能够看到的是，很多人会因此发生巨大的变 化......</p></blockquote><p>本来想假期期间能够跟上作业的进度，但自己迟迟不能完成。今天的思考与《5.为什么要格外重视视频号？》和《6. 为什么总是要更重视选择？》有关，也没有完全按读书笔记的方式进行。</p><p>放假了，要回老家，要陪小孩，反而不如上班时有固定的时间，也因为置换房子的事情，搞得有点焦头烂额，又要借钱，体会人情冷暖，又要和房东斗智斗勇，差点就要诉之法律了，同时也深刻体会了“只字不差地阅读”的重要性啊，如果不能搞定，那可能是20万的学费，还好后面协商解决了。</p><blockquote><p>我做过老师，我常常惊讶于那些受过高等教育的人连一纸租房合同或者雇佣合同都看不懂，或者忽视了关键条款，而最终吃了亏却只知道心疼钱，竟然不知道要反省一下“为什么我的阅读能力这么差？” —— 几乎无一例外地，他们都不认为自己的阅读能力有问题。</p></blockquote><p>妻子提出需要换房的时候，我一开始是反对的，但后面我还是同意了。买第一套房的时候，在公司股份和购房之间做选择，最终咬牙的房子房子。现在已经没有公司股份了，但还在公司的同事也说基本是套牢状态。而房子就算扣除了贷款，这些年下来也是涨了两倍了。那么现在即使知道BOX是个好资产，我也没有足够的说服力。然而我为什么同意了，我更多的时候承受不起，承受不起接下来生活的可能面临的300的抱怨。我是为家人呢？还是为自己呢？</p><blockquote><p>之前我们说过，绝大多数人缺的并不是机会和本钱，真正缺的是能力。但是，反过来， 在能力具备的情况下，错过机会就是极为可惜的事儿了，是吧?更何况，经过一小段时 间的学习与思考，你的认知，以及你的商业能力都有了很大的提升，所以，若是进步过 后的你竟然还是错过了机会，那么，肯定更为可惜......</p></blockquote><p>然后你就会想啊，如果用买房的这么用力，去投BOX自己会怎么样呢？</p>",13)])])}const n=t(c,[["render",a]]);export{b as __pageData,n as default};
